import type { LayoutView } from '../../src/layout-view.js';
import { render, type RenderResult } from '../../src/index.js';
import { describe, expect, it } from 'vitest';
// @ts-expect-error -- generated by bench/generate-render-fixtures.js (gitignored;
// `pnpm generate:bench-fixtures` writes it before this project runs), not a
// source file this package ships or type-checks against.
import fixtures from '../../../../bench/render-fixtures.json';

/**
 * F9 (execution plan §2.1): DD-09 §2's `< 16 ms` paint-only theme switch budget
 * lost its justification when F7 found the swap is a full `render()` plus an
 * `innerHTML` replacement, not a `<style>`-only patch — so the number that
 * actually matters is `render()`'s own cost, unmeasured until now. This times
 * `render()` **alone** (not the whole pipeline — `bench/generate-render-fixtures.js`
 * precomputes everything upstream of it in Node and ships the result as data) on
 * n50/n500/n2000 under both built-in themes, in headless Chromium and Firefox
 * (`vitest.config.ts`'s `browser` project, decision D3).
 *
 * Deliberately **not** a pass/fail assertion on 16 ms — timing asserts are flaky
 * in CI (D4). It prints median-of-N to the console; the numbers get copied into
 * this row of §2.1 and into `bench/README.md` by hand, and confirming or
 * renegotiating the budget itself is a human decision, not this test's.
 */

interface Fixture {
  readonly doc: string;
  readonly themeName: string;
  readonly styled: Parameters<typeof render>[0];
  readonly result: LayoutView;
  readonly theme: Parameters<typeof render>[2];
}

const FIXTURES = fixtures as readonly Fixture[];
const RUNS = 15;

function median(values: readonly number[]): number {
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 1 ? sorted[mid]! : (sorted[mid - 1]! + sorted[mid]!) / 2;
}

describe('F9 bench: render() alone (execution plan §2.1, DD-09 §2)', () => {
  for (const { doc, themeName, styled, result, theme } of FIXTURES) {
    it(`${doc} / ${themeName}`, () => {
      const times: number[] = [];
      let last: RenderResult | undefined;
      for (let i = 0; i < RUNS; i += 1) {
        const start = performance.now();
        last = render(styled, result, theme);
        times.push(performance.now() - start);
      }
      const m = median(times);
      // The bench's actual output; this file reports, it does not assert (D4).
      console.log(
        `[F9] ${doc} / ${themeName}: median ${m.toFixed(3)} ms over ${RUNS} runs (min ${Math.min(...times).toFixed(3)}, max ${Math.max(...times).toFixed(3)})`,
      );
      // Sanity only — proves render() actually ran on real input, not a perf gate.
      expect(last?.svg.length).toBeGreaterThan(0);
    });
  }
});

/**
 * Stage I part 2's own half of F9: DD-08 §6's actual live-view operation is
 * `render()` **followed by** `wrapper.innerHTML = result.svg` on a `<g>` —
 * that whole pair, not `render()` alone, is what a theme toggle costs on
 * screen. Builds the same detached `<svg><g class="rendered"></g></svg>`
 * `apps/web/src/canvas/Canvas.tsx` swaps into, in this project's real
 * Chromium/Firefox DOM (`document` is genuinely available here — `@vitest/browser`,
 * not jsdom), and times both steps together. Renegotiated budget (human
 * decision, 2026-09-23, execution plan §2.1): `< 16 ms` up to 500 nodes,
 * `< 50 ms` at 2 000, measured in Chromium.
 */
describe('F9 bench: render() + innerHTML swap (execution plan §2.1, DD-08 §6)', () => {
  for (const { doc, themeName, styled, result, theme } of FIXTURES) {
    it(`${doc} / ${themeName}`, () => {
      const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      const wrapper = document.createElementNS('http://www.w3.org/2000/svg', 'g');
      wrapper.setAttribute('class', 'rendered');
      svg.appendChild(wrapper);
      document.body.appendChild(svg);

      const times: number[] = [];
      try {
        for (let i = 0; i < RUNS; i += 1) {
          const start = performance.now();
          const rendered = render(styled, result, theme);
          wrapper.innerHTML = rendered.svg;
          times.push(performance.now() - start);
        }
      } finally {
        svg.remove();
      }

      const m = median(times);
      console.log(
        `[F9] ${doc} / ${themeName}: render()+swap median ${m.toFixed(3)} ms over ${RUNS} runs (min ${Math.min(...times).toFixed(3)}, max ${Math.max(...times).toFixed(3)})`,
      );
      expect(wrapper.children.length).toBeGreaterThan(0);
    });
  }
});
